const D = { scale:1, density:.5, energy:.62, speed:1, warp:.5, hue:44, x:.5, y:.5, style:'cymatic', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const PI = Math.PI;
const wh = h => ((h % 360) + 360) % 360;
const style = P.style;

const BW = 220, BH = Math.max(64, Math.round(BW * height / width));
if (!S.g || S.bw !== BW || S.bh !== BH) { S.g = createGraphics(BW, BH); S.g.pixelDensity(1); S.bw = BW; S.bh = BH; }

// seeded standing-wave modes (m,n integers) + rates/phases; rebuild on seed/section/density change
const sec = K.section | 0;
const NM = 3 + Math.round(P.density * 4);            // number of superposed plate modes
if (S.seedUsed !== P.seed || S.secUsed !== sec || S.nm !== NM) {
  S.seedUsed = P.seed; S.secUsed = sec; S.nm = NM;
  const fr = i => { const s = Math.sin(i*127.1 + P.seed*311.7 + sec*57.3)*43758.5453; return s - Math.floor(s); };
  const base = 2 + Math.round(P.scale * 4) + sec;    // higher plate frequency over sections -> finer figures
  S.modes = [];
  for (let k = 0; k < NM; k++) {
    S.modes.push({
      m: base + Math.round(fr(k*4+1) * (4 + P.scale*5)),
      n: base + Math.round(fr(k*4+2) * (4 + P.scale*5)),
      rate: 0.05 + fr(k*4+3) * 0.16,
      phase: fr(k*4+4) * 6.283,
      amp: 0.6 + fr(k*4+5) * 0.8
    });
  }
}

const g = S.g; g.loadPixels(); const px = g.pixels;
const modes = S.modes;
const eps = 0.05 + (1 - P.energy) * 0.14;             // nodal-line width (sand thickness); crisper at high energy
const hb = P.hue;
const t = K.t;
// precompute time-varying amplitudes (audio nudges on top of the K.t baseline)
const amps = new Float32Array(modes.length);
let anorm = 0;
for (let k = 0; k < modes.length; k++) {
  const a = modes[k].amp * (0.5 + 0.5 * Math.sin(t * modes[k].rate * (0.5 + P.speed) + modes[k].phase)) + A.mid * 0.3;
  amps[k] = a; anorm += Math.abs(a) * 0.9 + 0.1;
}
const inv = 1 / Math.max(0.001, anorm);
const cx = P.x, cy = P.y;

for (let j = 0; j < BH; j++) {
  const Y = (j / (BH - 1) - 0.5) * 2 * (0.6 + P.scale * 0.5) + (cy - 0.5) * 0.4 + 0.5; // 0..1-ish plate coord
  for (let i = 0; i < BW; i++) {
    const X = (i / (BW - 1) - 0.5) * 2 * (0.6 + P.scale * 0.5) + (cx - 0.5) * 0.4 + 0.5;
    let uSum = 0;
    for (let k = 0; k < modes.length; k++) {
      const md = modes[k];
      // symmetric superposition (Chladni): cos(mπX)cos(nπY) + cos(nπX)cos(mπY)
      uSum += amps[k] * (Math.cos(md.m*PI*X)*Math.cos(md.n*PI*Y) + Math.cos(md.n*PI*X)*Math.cos(md.m*PI*Y));
    }
    const uv = uSum * inv;                              // ~[-1,1]
    const au = Math.abs(uv);
    // sand collects at nodes (|u| ~ 0): high near lines, low elsewhere
    const sand = Math.max(0, 1 - au / eps);            // 1 on the nodal line -> 0 away
    const anti = Math.min(1, au * 1.1);                // antinode strength (for colored plate)
    let r, gg, b;
    const p = (j * BW + i) * 4;
    if (style === 'ferro') {                            // ferrofluid — dark spikes, warm rim
      const s = Math.pow(sand, 0.7);
      r = 0.05 + s * 0.9; gg = 0.03 + s * 0.55; b = 0.06 + s * 0.2;
    } else if (style === 'oscilloscope') {              // phosphor green lines on black
      const s = Math.pow(sand, 0.6);
      r = 0.02 + s * 0.3; gg = 0.05 + s * 1.0; b = 0.05 + s * 0.4;
    } else if (style === 'ink') {                        // named mono — black sand on cream plate
      const s = Math.pow(sand, 0.65);
      const paper = 0.92 - s * 0.86; r = paper; gg = paper * 0.98; b = paper * 0.9;
    } else if (style === 'spectral') {                  // plate tinted by antinode phase, bright sand
      const hh = wh(hb + uv * 120 + sec * 20) / 360;
      const c0 = 0.5 + 0.5*Math.cos(6.2831*(hh+0.00)), c1 = 0.5 + 0.5*Math.cos(6.2831*(hh+0.33)), c2 = 0.5 + 0.5*Math.cos(6.2831*(hh+0.66));
      const plate = 0.10 + anti * 0.32;
      const s = Math.pow(sand, 0.7);
      r = c0 * plate + s; gg = c1 * plate + s; b = c2 * plate + s;
    } else {                                             // cymatic (default) — gold sand on deep indigo plate
      const plate = 0.06 + anti * (0.10 + P.energy * 0.18);
      const s = Math.pow(sand, 0.7) * (0.8 + P.energy * 0.5);
      const hh = wh(hb + uv * 30) / 360;
      const gold0 = 1.0, gold1 = 0.82, gold2 = 0.35;
      r = plate * 0.35 + s * gold0;
      gg = plate * 0.30 + s * gold1;
      b = plate * 0.85 + s * gold2;
    }
    px[p]   = Math.max(0, Math.min(255, r * 255));
    px[p+1] = Math.max(0, Math.min(255, gg * 255));
    px[p+2] = Math.max(0, Math.min(255, b * 255));
    px[p+3] = 255;
  }
}
g.updatePixels();

push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height);
pop();
